// Coverage is meaningful only if records are distinct, readable and traceable to every topic and domain.
test("five domains contain ten topics and 120 distinct traceable originals", () => {
  assert.equal(articles.length, 120);
  assert.equal(topics.length, 10);
  for (const field of ["id", "evidence", "title", "content"] as const)
    assert.equal(new Set(articles.map((a) => a[field])).size, 120);
  for (const category of categories)
    assert.equal(topics.filter((t) => t.category === category).length, 2);
  for (const topic of topics) {
    const records = articles.filter((a) => a.topicId === topic.id);
    assert.ok(records.length >= 8);
    assert.equal(new Set(records.map((a) => a.source)).size, 4);
    assert.equal(new Set(records.map((a) => a.sentiment)).size, 3);
    assert.equal(records.length, topic.count);
    assert.equal(
      topic.negative,
      Number(
        (
          (records.filter((a) => a.sentiment === "负面").length /
            records.length) *
          100
        ).toFixed(1),
      ),
    );
    const risk = initialRisks.find((r) => r.topic === topic.id)!;
    assert.equal(risk.count, topic.count);
    assert.equal(risk.growth, `${topic.change}%`);
    assert.equal(risk.level, topic.risk);
    for (const record of records) {
      assert.equal(record.topic, topic.title);
      assert.equal(record.category, topic.category);
      assert.ok(record.content.length >= 65);
      assert.ok(record.content.includes(record.quote));
      assert.ok(Date.parse(record.observedAt) > snapshotEpoch - 24 * 3600000);
      assert.ok(Date.parse(record.observedAt) <= snapshotEpoch);
    }
  }
  assert.doesNotMatch(JSON.stringify(articles), /校园|学校|家校/);
});

// Independent aggregations catch drift in sources, time charts, domain heatmaps and sentiment counts.
test("charts, sources and alerts reconcile to the same original records", () => {
  assert.equal(
    sourceRows.reduce((n, s) => n + s.count, 0),
    articles.length,
  );
  assert.equal(
    observationSeries().reduce((n, p) => n + p.value, 0),
    articles.length,
  );
  assert.equal(
    observationSeries().reduce((n, p) => n + p.negative, 0),
    articles.filter((a) => a.sentiment === "负面").length,
  );
  for (const row of domainActivity())
    assert.equal(
      row.values.reduce((a, b) => a + b, 0),
      articles.filter((a) => a.category === row.category).length,
    );
  assert.equal(
    observationSeries("7天").at(-2)?.value,
    topics.reduce((n, t) => n + t.previousCount, 0),
  );
  assert.equal(initialRisks.length, topics.length);
});

// A focused report must never borrow evidence from an unrelated topic in the same domain.
test("report membership, per-topic summaries and exports share the same scope", () => {
  const state = createMobileState();
  const focus = state.reports.find((r) => r.topicId === focusTopicId)!;
  assert.equal(focus.evidenceIds.length, 18);
  assert.equal(reportDocuments("食品安全").length, 30);
  assert.equal(reportDocuments("食品安全", false, focusTopicId).length, 18);
  for (const report of state.reports) {
    const stats = reportTopicMetrics(report);
    assert.equal(
      stats.reduce((n, t) => n + t.count, 0),
      report.evidenceIds.length,
    );
    assert.equal(
      stats.reduce((n, t) => n + t.negativeCount, 0),
      articles.filter(
        (a) => report.evidenceIds.includes(a.id) && a.sentiment === "负面",
      ).length,
    );
  }
  assert.match(reportMarkdown(focus), /18 条原文/);
  assert.doesNotMatch(reportMarkdown(focus), /外卖配送食品安全/);
  const changed = withdrawSource(state);
  assert.equal(
    reportMarkdown(
      changed.reports.find((r) => r.id === focus.id)!,
      true,
    ),
    "",
  );
  const updated = approveReport(
    rebuildReport(changed, focus.id),
    focus.id,
    true,
  ).reports.find((r) => r.id === focus.id)!;
  assert.equal(updated.evidenceIds.length, 17);
  assert.equal(reportTopicMetrics(updated)[0].negativeCount, 7);
  assert.doesNotMatch(reportMarkdown(updated, true), /EVD-20261103-001/);
});

// Old approvals cannot move to different originals; the full previous workspace must be archived first.
test("dataset migration archives old work before starting the new case", () => {
  const old = {
    ...createMobileState(),
    datasetVersion: "legacy",
    withdrawn: true,
    collaboration: {
      phase: "completed",
      analysis: "旧场景记录",
      feedback: "已审核",
      events: [],
    },
  };
  const raw = JSON.stringify(old);
  const saved: string[] = [];
  const migrated = restoreDataset(raw, (version, original) => {
    assert.equal(version, "legacy");
    saved.push(original);
  });
  assert.deepEqual(saved, [raw]);
  assert.equal(migrated.datasetVersion, datasetVersion);
  assert.equal(migrated.withdrawn, false);
  assert.equal(migrated.collaboration.phase, "identified");
  assert.throws(
    () =>
      restoreDataset(raw, () => {
        throw new Error("storage full");
      }),
    /storage full/,
  );
  const current = createMobileState();
  current.following = ["TOP-009"];
  assert.deepEqual(
    restoreDataset(JSON.stringify(current), () => {
      assert.fail("current version must not be archived");
    }),
    current,
  );
});
